"enemy_burrower": {"enemyGuide":true,"type":"enemy","title":"掘地蟲","detail":{"經驗值":"60","現身條件":"與話多的守衛（-24, -53）交談。答應清剿掘地蟲、拒絕、走戰士或聖騎士的專屬選項，或因金幣不足無法付費時，會觸發掘地蟲現身。"},"sprite":"mtile_enemy","rotation":0,"native":null,"nativeRotation":0,"isChest":false},
"enemy_demo_snake": {"enemyGuide":true,"type":"enemy","title":"草牙","detail":{"經驗值":"70","現身條件":"在（16, -42）探索樹洞。蛇還在洞裡時，伸手進去、用樹枝或武器試探，或用戰士選項踢石堆。"},"sprite":"mtile_enemy","rotation":0,"native":null,"nativeRotation":0,"isChest":false},
